#!/usr/bin/env python3
"""Some portions generated by Codex. Validate all runs, summarize independent fork means."""
import json, pathlib, statistics, sys
root=pathlib.Path(sys.argv[1])
def records(file, prefix):
    out=[]
    for line in file.read_text().splitlines():
        if line.startswith(prefix+' '):
            out.append(dict(token.split('=',1) for token in line.split()[1:]))
    if not out: raise ValueError(f'No {prefix} records: {file}')
    return out
reference=records(root/'reference.log','audit')[0]
key=('rows','checksum','checksum2')
results={}
for regime in ('regular','interpreted','janino','coscan'):
    forks={'A':[], 'B':[]}
    checks=set()
    for file in sorted(root.glob(regime+'-*-*.log')):
        variant=file.stem.split('-')[-1]
        rows=records(file,'coscan' if regime=='coscan' else 'audit')
        for r in rows:
            if regime!='coscan' and any(r[k]!=reference[k] for k in key):
                raise ValueError(f'Reference mismatch: {file} {r}')
            if regime=='coscan': checks.add((r['triples'],r['resultRows'],r['checksum']))
        measured=[r for r in rows if int(r['run'])>=0]
        if not measured: raise ValueError(f'No measurements: {file}')
        forks[variant].append({'file':file.name,'meanMs':statistics.mean(int(r['totalNs'])/1e6 for r in measured),
            'minMs':min(int(r['totalNs'])/1e6 for r in measured),
            'maxMs':max(int(r['totalNs'])/1e6 for r in measured),
            'firstRowMeanMs':None if regime=='coscan' else statistics.mean(int(r['firstRowNs'])/1e6 for r in measured)})
    if len(forks['A'])!=4 or len(forks['B'])!=4: raise ValueError(f'Incomplete forks: {regime}')
    if regime=='coscan' and len(checks)!=1: raise ValueError(f'coScan mismatch: {checks}')
    a=statistics.mean(x['meanMs'] for x in forks['A']); b=statistics.mean(x['meanMs'] for x in forks['B'])
    results[regime]={'forks':forks,'baselineMeanMs':a,'candidateMeanMs':b,
                    'latencyReductionPercent':100*(1-b/a),'throughputIncreasePercent':100*(a/b-1)}
print(json.dumps({'scope':'fresh ba74f478-derived A/B, not main; repository query controls and operator coScan',
                  'reference':{k:reference[k] for k in key},'results':results},indent=2))
